`,e.jsxs(i.li,{children:["Region key of the format (",e.jsx(i.code,{children:"[table],[region start key],[region id]"}),")"]}),`
`]}),`
`,e.jsx(i.p,{children:e.jsx(i.strong,{children:"Values:"})}),`
